text:
Here is a simple expense tracker. Add what you spent, pick a category, and the total and category split update as you go. Entries stay only while this page is open, so note down anything you want to keep.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#fafafa;color:#222}
h1{font-size:18px;margin:0 0 12px}
.card{background:#fff;border:1px solid #ddd;border-radius:10px;padding:12px;margin-bottom:12px}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{font:inherit;padding:8px;border:1px solid #bbb;border-radius:6px}
input{flex:1;min-width:110px}
button{background:#2a6df4;color:#fff;border:0;cursor:pointer}
button.x{background:#eee;color:#a00;padding:4px 8px}
.big{font-size:24px;font-weight:600}
.bar{height:10px;background:#2a6df4;border-radius:5px}
.cat{display:flex;align-items:center;gap:8px;margin:6px 0;font-size:14px}
.cat span:first-child{width:90px}.cat div{flex:1;background:#eee;border-radius:5px}
.cat span:last-child{width:90px;text-align:right}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
.over{color:#c00}.ok{color:#080}
small{color:#666}
</style></head><body>
<h1>Monthly expenses</h1>
<div class="card">
<div class="row"><input id="what" placeholder="What for?"><input id="amt" type="number" min="0" placeholder="Amount (₹)"></div>
<div class="row"><select id="cat"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Other</option></select>
<input id="date" type="date"><button id="add">Add</button></div>
</div>
<div class="card">
<small id="mon">This month</small>
<div class="big" id="total">₹0</div>
<div class="row" style="margin-top:8px"><input id="budget" type="number" min="0" placeholder="Monthly budget (₹)"></div>
<div id="left"></div>
</div>
<div class="card"><b>By category</b><div id="cats"></div></div>
<div class="card"><b>Entries</b><div id="list"><small>Nothing added yet.</small></div></div>
<script>
var items=[],$=function(i){return document.getElementById(i)};
var fmt=function(n){return "₹"+Math.round(n).toLocaleString("en-IN")};
$("date").value=new Date().toISOString().slice(0,10);
function render(){
var t=0,by={};
items.forEach(function(e){t+=e.a;by[e.c]=(by[e.c]||0)+e.a});
$("total").textContent=fmt(t);
var b=parseFloat($("budget").value)||0;
$("left").innerHTML=b?(t>b?'<span class="over">Over budget by '+fmt(t-b)+'</span>':'<span class="ok">'+fmt(b-t)+' left of '+fmt(b)+'</span>'):'';
var h="";Object.keys(by).sort(function(x,y){return by[y]-by[x]}).forEach(function(k){
h+='<div class="cat"><span>'+k+'</span><div><div class="bar" style="width:'+(by[k]/t*100)+'%"></div></div><span>'+fmt(by[k])+'</span></div>'});
$("cats").innerHTML=h||"<small>No data yet.</small>";
var l="";items.slice().sort(function(x,y){return y.d.localeCompare(x.d)}).forEach(function(e){
l+='<div class="item"><span>'+e.w+'<br><small>'+e.c+' · '+e.d+'</small></span><span>'+fmt(e.a)+' <button class="x" data-id="'+e.id+'">✕</button></span></div>'});
$("list").innerHTML=l||"<small>Nothing added yet.</small>";
}
$("add").onclick=function(){
var a=parseFloat($("amt").value);
if(!(a>0))return;
var w=$("what").value.trim()||$("cat").value;
items.push({id:Date.now()+Math.random(),w:w.replace(/[<>&]/g,""),a:a,c:$("cat").value,d:$("date").value});
$("what").value="";$("amt").value="";render();
};
$("budget").oninput=render;
$("list").onclick=function(ev){
var id=ev.target.getAttribute("data-id");
if(id){items=items.filter(function(e){return String(e.id)!==id});render()}
};
render();
</script></body></html>
```
